window.RP_SESSION={"id":"S-07ebbbd8fac1","messages":[{"id":"RP-III-0073525","time":"2026-04-12T01:04:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"수도. 중앙 교회.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073526","time":"2026-04-12T01:07:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"다른 종교의 사제를 찾아가서 치료를 부탁하는건 매우 자존심이 상하는 일이었지만, 수도 근처인 길드 건물 근처에서 찾을 수 있는 가장 강력한 사제는 당연히 수도의 중앙 교회에 있다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073527","time":"2026-04-12T01:07:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"스카일라의 어떤 건물보다도 으리으리하고 휘황찬란한 이 건물이, 왕성도 아니고 교회라니...","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073528","time":"2026-04-12T01:09:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"님드 앗질랄 아스사피 빈 칼리드 알 쿠라이시는 새삼 세상이 넓은 것을 깨닫는다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073529","time":"2026-04-12T01:10:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"하지만 지금 그는 갑옷 안에 든 팔을 뺄 새도 없이 급하게 달려가고 있는 중이었고, 깊이 생각할 겨를도 없다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073530","time":"2026-04-12T01:15:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 주교, 주교 각하를 불러 주시오. \"\n\n잘린 팔을 보자마자 무슨 일인지 대충 짐작한 부제들이 우연히 하루 일과를 마치고 잠에 들려고 이동중이던 주교 한 명을 불러세운다.\n\n\" 주교 각하. 제가 비록 라운데라교의 신자는 아니지만 도움을 간청하고자 합니다. 신의 명령을 따라 사이한 샤이탄(라운데라교의 언어로는 사탄)같은 자와 싸우다가 팔을 잃었으되, 찾아올 수 있는 주교가 마침 이곳에 계셨으니, 이는 서로를 만나 화합하라는 계시가 아니겠나이까. \"","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073531","time":"2026-04-12T01:16:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 예. \"","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073532","time":"2026-04-12T01:16:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 부탁을... 말씀하십니까. 예. \"","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073533","time":"2026-04-12T01:16:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 여부가 있겠습니까. 그리 하겠습니다. \"","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073534","time":"2026-04-12T01:18:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"주교가 님드의 팔을 붙이기 위해 신성을 사용한다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073535","time":"2026-04-12T01:18:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!운명+4","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073536","time":"2026-04-12T01:18:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 11 + 4 = 15\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-III-0073537","time":"2026-04-12T01:19:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 그런 부탁이라면 부탁이 아니라 명령이라도 듣겠습니다. \"","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073538","time":"2026-04-12T01:19:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073539","time":"2026-04-12T01:19:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]},{"id":"RP-III-0073540","time":"2026-04-12T01:19:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"...","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073541","time":"2026-04-12T01:19:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"계속된다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073542","time":"2026-04-12T01:20:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"님드는 물리적으로야 붙긴 했지만 아직 움직이지는 않는 팔로부터 쌓여 있던 독소가 혈관으로 돌아와 슬슬 따가워지는 것을 느끼면서.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073543","time":"2026-04-12T01:20:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"길드 건물로 돌아가지 않고 수도의 어두운 곳으로 간다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073544","time":"2026-04-12T01:21:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"' 당신이 라운데라의 사람이 아니라면 라운데라의 교회에 공물을 바치는 것은 당신의 양심에도, 우리의 양심에도 적절치 않으니. 바치려 했던 공물을 모든 이들의 주님께 봉헌하시오. 이것이 진정한 보속이오. '","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073545","time":"2026-04-12T01:21:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"모든 이들의 주님? 모든 이들의 주님?","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073546","time":"2026-04-12T01:22:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"나에게 찬란하신 라 엘라와 고귀하신 바슈르 외에 주님이 또 있다는 말인가? 주교에게 라운데라 외에 주님이 또 있다는 말인가?","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073547","time":"2026-04-12T01:22:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"님드는 자신도 모르게 어딘가로 걸으면서 계속 되뇌인다. 그는 자신이 어디로 가고 있는지도 모른다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073548","time":"2026-04-12T01:23:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"여기가 길드 건물로 돌아가는 길이 아니라는 사실조차 인지하지 못한 채, 주교의 말에 푹 빠져서 헤매이고 있다가.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073549","time":"2026-04-12T01:25:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"어떤 거렁뱅이와 툭, 부딪히고 나서야 자신이 수도의 뒷골목. 가장 어두운 공간에 들어왔다는 사실을 깨닫는다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073550","time":"2026-04-12T01:25:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"모든 이들의 주님? 모든 이들의 주님?","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073551","time":"2026-04-12T01:26:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"이런 자들에게도 주님이 있다는 말인가? 이런 거렁뱅이들, 잡배들, 범죄자들, 더러운 쓰레기들에게도 주님이 있다는 말인가?","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073552","time":"2026-04-12T01:27:00+09:00","room":"RP III","name":"존","profile":"존","identity":"unresolved","type":"dialogue","body":"?","characters":[]},{"id":"RP-III-0073553","time":"2026-04-12T01:27:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"저런 거지에게도?","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073554","time":"2026-04-12T01:30:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"...","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073555","time":"2026-04-12T01:30:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"...","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073556","time":"2026-04-12T01:30:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"...","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073557","time":"2026-04-12T01:31:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"님드는 길드로 돌아가기 전에 생각을 정리할 시간이 더 필요했다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073558","time":"2026-04-12T01:32:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"새로이 붙은 이 팔의 대가로 제시된 모든 이들의 주님이란 무엇인가. 어떻게 찾아야 하는가.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073559","time":"2026-04-12T01:32:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"쿠란은 분명 저들의 성경에 예언자 무함마드가 받은 마지막 계시를 덧붙인 것이고, 저들의 경전은 완성된 것이 아닌데. 오히려 내가 읽지 못한 글을 저들의 주교는 읽었단 말인가?","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073560","time":"2026-04-12T01:34:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"아니야. 그랬다면 그들은 내가 모른다는 사실을 알았을 것이고, 따로 그 부분을 읽어 주었을 것이다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073561","time":"2026-04-12T01:34:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"모든 이들의 주님이란 깨달음이다. 모든 이들의 주님에게 가는 길에는 깨달음이 있다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073562","time":"2026-04-12T01:34:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"깨달음.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073563","time":"2026-04-12T01:34:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!의지","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073564","time":"2026-04-12T01:34:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'님드 알 쿠라이시'의 의지 판정 :\n[10] + [3] = [13]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-III-0073565","time":"2026-04-12T01:34:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"너 스스로.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073566","time":"2026-04-12T01:35:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"계시가 돌아왔다. 하지만 그 내용은 ' 너 스스로. '","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073567","time":"2026-04-12T01:35:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"알쏭달쏭. 알 수가 없다. 모르겠다. 이렇게까지 모호한 대답은 얻은 바가 없다. 유일한 힌트는, 그 물음이 카카투의 뜻을 거스르지는 않는다는 것. 그 하나 뿐.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073568","time":"2026-04-12T01:36:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그저 마음을 조금 가볍게 먹고 주위를 둘러볼 계기가 되었을 뿐이다. 신은 언제나 그렇게 돕는다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073569","time":"2026-04-12T01:37:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"주변을 둘러보자 가난한 자들이 다시 눈에 보인다. 아까 이미 봤던 광경이라 눈을 돌리려던 순간.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073570","time":"2026-04-12T01:38:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그들이 서로 한 조각의 빵을 나눠 먹는 모습이 보였다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073571","time":"2026-04-12T01:38:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"앙상하고 더러운 손이 그 자그맣고 검은 빵을 찢었다. 그리고 서로에게 나누었다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073572","time":"2026-04-12T01:38:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"모든 이들의 주님?","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073573","time":"2026-04-12T01:39:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"모든 이들의 주님?","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073574","time":"2026-04-12T01:41:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"님드는 불현듯 깨달은 것이 있어 그 야트막한 언덕을 달려내려갔다. 그리고 지난 임무에서 자신의 몫으로 받은 골드를 모두 털어 가장 먼저 보이는 빵집에서 좋은 빵과 채소, 삶은 고기를 가득 산다. 엄청난 양의 음식들이 몇 개의 수레를 가득 채우고도 남는다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073575","time":"2026-04-12T01:42:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"수 골드만 있어도 이런 것을 할 수 있었잖아.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073576","time":"2026-04-12T01:43:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073577","time":"2026-04-12T01:43:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'님드 알 쿠라이시'의 힘 판정 :\n[7] + [3] = [10]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-III-0073578","time":"2026-04-12T01:43:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"님드 앗질랄 아스사피 빈 칼리드 알 쿠라이시는 당장 움직이는 한 팔만으로 초인적인 힘을 내서 커다란 수레를 밀고 언덕을 오른다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073579","time":"2026-04-12T01:43:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"하지만...","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073580","time":"2026-04-12T01:43:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!힘-3","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073581","time":"2026-04-12T01:43:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'님드 알 쿠라이시'의 힘 판정 :\n[3] + [3] + [-3] = [3]\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-III-0073582","time":"2026-04-12T01:44:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"더 이상. 움직이지 않으러던 순간에.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073583","time":"2026-04-12T01:44:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"오늘 장사를 마치고 집에 가려던 푸줏간 주인, 빵집 주인, 야채 장수가 수레에 손을 얹는다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073584","time":"2026-04-12T01:45:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"덕불고 필유린.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073585","time":"2026-04-12T01:45:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"사람들이 힘을 모아 수레를 끌고 나아가기 시작한다. 혼자서는 할 수 없었을 일이 벌어지기 시작한다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073586","time":"2026-04-12T01:46:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"한 편, 그 시각. 달동네의 빈민들은 가진 것을 나누어 먹기 위해 서로 가져온 빵과 물고기를 모았다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073587","time":"2026-04-12T01:46:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"다섯 조각의 빵과 두 마리의 물고기.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073588","time":"2026-04-12T01:47:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"unresolved","type":"dialogue","body":"오~병이어.","characters":[]},{"id":"RP-III-0073589","time":"2026-04-12T01:48:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"오병이어.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073590","time":"2026-04-12T01:49:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"빈민들은 그 빵과 물고기를 가지고 누가 숨겼네, 더 가지고 있네 하며 서로 싸우고, 욕하고, 주먹을 들면서도 결국은 그렇게 살아가는 사람들이었다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073591","time":"2026-04-12T01:49:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그렇게 살아가는 사람들.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073592","time":"2026-04-12T01:50:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"왁자지껄하게 떠들던 사람들은 정말로 서로가 가진 것이 더 없다는 것을 확인하고는 인원수에 맞게 빵과 물고기를 조금씩 잘라 먹기 시작하였다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073593","time":"2026-04-12T01:50:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"하지만 그러면서도 누가 더 가져가네, 누가 덜 가져가네 하며 서로 싸우고, 욕하고, 주먹을 들면서도 결국은 그렇게 살아가는 사람들이었다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073594","time":"2026-04-12T01:51:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그 때, 님드와 세 명의 가게 주인들이. 사람들이 모인 공터 어귀에서 수레를 끌고 저벅저벅 걸어왔다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073595","time":"2026-04-12T01:52:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"네 명의 건장한 장정이, 한 명은 갑옷을 입고 푸줏간 주인을 포함 두 명이 칼까지 차고 있으니. 아무리 거지같이 사는 사람들이라도 함부로 약탈을 하지 못하리라.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073596","time":"2026-04-12T01:53:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"가난뱅이들은 벌벌 떨며 숨죽이고 있다. 하지만","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073597","time":"2026-04-12T01:53:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"님드는 빵을 손에 들고 하늘을 우러러 감사의 기도를 드린 다음, 빵을 떼어 함께 온 이들에게 주었다. 그들은 그것을 사람들에게 나누어주었다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073598","time":"2026-04-12T01:54:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"몇 년, 길게는 몇십 년 만에 처음으로 제대로 된 음식을 먹게 생긴 가난뱅이들은 수 골드 어치의 음식을 눈코 뜰 새 없이 흡입하기 시작했다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073599","time":"2026-04-12T01:57:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"사람들은 모두 배불리 먹었다. 그리고 남은 조각을 주워 모으니 열두 바구니에 가득 찼다.","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073600","time":"2026-04-12T01:57:00+09:00","room":"RP III","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-f310b84f8f20"]},{"id":"RP-III-0073601","time":"2026-04-12T01:57:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
